#pragma once

struct StrictStarOwnerObserver {
 U N,burn,every,post=0;int orientation,nr,nc,owner_width;
 std::vector<int>labels;std::vector<I>weights;std::vector<std::vector<U>>counts;
 std::vector<std::pair<U,std::vector<int>>>records;
 StrictStarOwnerObserver(const Graph&g,const FixedProbeStatistics&q,const StrictStarFullFiber&s,U n,U b,U cadence):N(n),burn(b),every(cadence),orientation(s.orientation),nr(g.nr),nc(g.nc),owner_width(orientation?g.nc:g.nr){
  if(!s.certificate||!every||N%640||every!=N/640||burn!=N/5)throw std::runtime_error("strict owner requires certificate and641/512schedule");
  std::set<int>selected;for(const auto&c:q.cells){int j=orientation?c.r:c.c;if(j!=s.hub&&g.target_degree[orientation?j:g.nr+j]==1)selected.insert(j);}
  if(selected.size()>64)throw std::runtime_error("strict owner selectedlabels>64");
  for(int j:selected){labels.push_back(j);weights.push_back(g.target_strength[orientation?j:g.nr+j]);}
  counts.assign(labels.size(),std::vector<U>(owner_width));records.reserve(641);record(g,0);
 }
 void record(const Graph&g,U t){if(t!=records.size()*every||t>N)throw std::runtime_error("strict owner checkpoint order");std::vector<int>owners;owners.reserve(labels.size());for(size_t j=0;j<labels.size();++j){const auto&a=g.adj[orientation?labels[j]:g.nr+labels[j]];if(a.size()!=1)throw std::runtime_error("strict owner live degree");const Edge e=g.edges[a[0]];const int owner=orientation?e.c:e.r,object=orientation?e.r:e.c;if(object!=labels[j]||owner<0||owner>=owner_width||e.w!=weights[j])throw std::runtime_error("strict owner live forced label");owners.push_back(owner);if(t>burn)++counts[j][owner];}if(t>burn)++post;records.emplace_back(t,std::move(owners));}
 void observe(const Graph&g,U t){if(t%every==0||t==N)record(g,t);}
 void write(const std::string&prefix)const{if(records.size()!=641||records.back().first!=N||post!=512)throw std::runtime_error("strict owner schedule totals");for(const auto&v:counts){U sum=0;for(U x:v)sum+=x;if(sum!=512)throw std::runtime_error("strict owner histogram total");}
  std::ofstream tr(prefix+".full_owner.trace.jsonl");for(const auto&r:records){tr<<"{\"iteration\":"<<r.first<<",\"owners\":[";for(size_t j=0;j<r.second.size();++j)tr<<(j?",":"")<<r.second[j];tr<<"]}\n";}if(!tr)throw std::runtime_error("strict owner trace output");
  std::ofstream f(prefix+".full_owner_counts.json");f<<"{\"format\":\"query_selected_private_full_owner_v1\",\"nr\":"<<owner_width<<",\"graph_nr\":"<<nr<<",\"graph_nc\":"<<nc<<",\"owner_axis\":\""<<(orientation?"column":"row")<<"\",\"object_axis\":\""<<(orientation?"row":"column")<<"\",\"outer_budget\":"<<N<<",\"burn_outer\":"<<burn<<",\"trace_records\":641,\"postburn_count\":512,\"column_labels\":[";for(size_t j=0;j<labels.size();++j)f<<(j?",":"")<<labels[j];f<<"],\"object_labels\":[";for(size_t j=0;j<labels.size();++j)f<<(j?",":"")<<labels[j];f<<"],\"leaf_weights\":[";for(size_t j=0;j<weights.size();++j)f<<(j?",":"")<<weights[j];f<<"],\"owner_counts\":[";for(size_t j=0;j<counts.size();++j){if(j)f<<',';f<<'[';for(size_t u=0;u<counts[j].size();++u)f<<(u?",":"")<<counts[j][u];f<<']';}f<<"],\"lookup_policy\":\"live degree1 object adjacency; original labels and all owner coordinates; O(1) per selected label; no RNG or mutation\"}\n";if(!f)throw std::runtime_error("strict owner histogram output");
 }
};
static int run_strict_star(Engine&e,Graph&g,StrictStarFullFiber&s,bool fixed_class,bool structure_request,bool owner_request,const std::string&out,const std::string&queries,U seed,U N,U B,U trace,U check,U hist,double cpu_start,Clock::time_point start){
 if(!g.check()||g.D)throw std::runtime_error("strict star bad margins");if(hist&&U(g.nr)*U(g.nc)>64)throw std::runtime_error("histogram only small");
 FixedProbeStatistics observer(g,B,N,queries,0,trace);UnlabeledStructureTrace structure;structure.initialize(g,structure_request,out,B,N,trace);
 std::unique_ptr<StrictStarOwnerObserver>owner;if(owner_request)owner=std::make_unique<StrictStarOwnerObserver>(g,observer,s,N,B,trace);
 std::map<std::string,U>counts;std::vector<std::pair<U,std::string>>snapshots;U checks=1,changed=0;const double setup_cpu=process_cpu()-cpu_start;
 for(U t=1;t<=N;++t){changed+=s.step(e,g,fixed_class);++e.stat.outer;observer.observe(g,t,e.stat.cell_updates);structure.observe(g,t);if(owner)owner->observe(g,t);if(hist&&t>B){const std::string state=g.flat();++counts[state];if(trace&&t%trace==0)snapshots.emplace_back(t,state);}if((check&&t%check==0)||t==N){if(!g.check()||g.D)throw std::runtime_error("strict star four margins changed");++checks;}}
 structure.finish();const double loop_cpu=process_cpu()-cpu_start-setup_cpu;observer.write(out);if(owner)owner->write(out);
 if(hist){std::ofstream f(out+".hist.json");f<<"{\"postburn_count\":"<<N-B<<",\"counts\":{";bool first=true;for(const auto&p:counts){if(!first)f<<',';first=false;f<<'\"'<<p.first<<"\":"<<p.second;}f<<"},\"snapshots\":[";first=true;for(const auto&p:snapshots){if(!first)f<<',';first=false;f<<"["<<p.first<<",\""<<p.second<<"\"]";}f<<"]}\n";if(!f)throw std::runtime_error("strict histogram output");}
 std::ofstream final(out+".final.graph");final<<g.nr<<' '<<g.nc<<'\n';for(const auto&ed:g.edges)final<<ed.r<<' '<<ed.c<<' '<<ed.w<<'\n';final.close();if(!final)throw std::runtime_error("strict star graph output");
 const double cpu=process_cpu()-cpu_start,wall=std::chrono::duration<double>(Clock::now()-start).count();std::ofstream f(out+".run.json");f<<std::setprecision(17)<<'{';s.metadata(f,true,fixed_class);f<<"\"status\":\"ok\",\"design\":\"strict_star_complete_fiber_compiler\",\"all_margins_passed\":true,\"uniform_target_claim\":true,\"seed\":"<<seed<<",\"outer_budget\":"<<N<<",\"burn\":"<<B<<",\"burn_outer\":"<<B<<",\"outer\":"<<e.stat.outer<<",\"postburn\":"<<N-B<<",\"cpu_seconds\":"<<cpu<<",\"setup_cpu_seconds\":"<<setup_cpu<<",\"loop_cpu_seconds\":"<<loop_cpu<<",\"wall_seconds\":"<<wall<<",\"rss_kib\":"<<proc_memory("VmHWM")<<",\"checks\":"<<checks<<",\"changed_macro\":"<<changed<<",\"cell_updates\":"<<e.stat.cell_updates<<",\"coverage_calls\":0,\"composed_R_calls\":0,\"GWS_calls\":0,\"PJ_calls\":0,\"WS_calls\":0,\"RC_calls\":0,\"COHORT_calls\":0,\"MA_active\":false,\"GWS_active\":false,\"factorized_active\":false,\"dynamic_support_bitset_scene_active\":false,\"strict_star_full_owner_observer\":"<<(owner_request?"true":"false")<<",\"full_owner_trace_records\":"<<(owner?owner->records.size():0)<<",\"full_owner_postburn_records\":"<<(owner?owner->post:0)<<",\"structure_trace_requested\":"<<(structure_request?"true":"false")<<",\"structure_trace_records\":"<<structure.snapshots<<",\"structure_postburn_records\":"<<structure.postburn_snapshots<<",\"strict_star_policy\":\"complete two-weight four-margin fiber; cached immutable grouped counts; t>=1 exact IID only in exact mode; no A/B/M/R/GWS; fixed_class fine projection preserves initial class composition; relative normalizer not canonical F count\"}\n";if(!f)throw std::runtime_error("strict star run output");return 0;
}
